import sys
from collections import deque

def build_tree(tokens):
    if not tokens or tokens[0] == 'N':
        return None
    root = TreeNode(int(tokens[0]))
    q = deque([root])
    i = 1
    n = len(tokens)
    while q and i < n:
        node = q.popleft()
        # left child
        if i < n and tokens[i] != 'N':
            node.left = TreeNode(int(tokens[i]))
            q.append(node.left)
        i += 1
        # right child
        if i < n and tokens[i] != 'N':
            node.right = TreeNode(int(tokens[i]))
            q.append(node.right)
        i += 1
    return root

class TreeNode:
    __slots__ = ('val', 'left', 'right')
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def max_path_sum(root):
    # returns maximum sum from this node to any leaf beneath it
    if root is None:
        # should not be reached for valid inputs
        return -10**18
    if root.left is None and root.right is None:
        return root.val
    best = -10**18
    if root.left:
        best = max(best, max_path_sum(root.left))
    if root.right:
        best = max(best, max_path_sum(root.right))
    return root.val + best

def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    t = int(data[0].strip())
    idx = 1
    for _ in range(t):
        while idx < len(data) and data[idx].strip() == '':
            idx += 1  # skip blank lines if any
        tokens = data[idx].strip().split()
        idx += 1
        root = build_tree(tokens)
        print(max_path_sum(root))

if __name__ == "__main__":
    main()

