def sieve_of_eratosthenes(n, limit):
    if n < 2 or limit <= 0:
        return []
    is_prime = [True] * (n + 1)
    p = 2
    while p * p <= n:
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1
    prime_numbers = [i for i in range(2, n + 1) if is_prime[i]]
    return prime_numbers[:limit]

def main():
    n = int(input())
    limit = int(input())
    print(sieve_of_eratosthenes(n, limit))

