        except EOFError:
            break
        if cmd == "end":
            break
        if cmd.startswith("push "):
            _, num = cmd.split()
            stack.push(int(num))
        elif cmd == "pop":
            stack.pop()
        elif cmd == "peek":
            stack.peek()

