use num_traits::FromPrimitive; // crate for enabling division by 2
use std::cmp::Ord; // trait for comparison

// We define our function assertive_median to take a vector of type T and a function that can compare
// two values of type T. It will return an Option<T> in which the median of the sortable vector is wrapped.
// We use Option<T> as it is idiomatic in Rust to represent the possibility of absence in a more type-safe manner.

pub fn assertive_median<T>(l: &Vec<T>, cmp_func: impl Fn(&T, &T) -> std::cmp::Ordering) -> Option<T> 
where 
    T: Copy + FromPrimitive + Ord, 
{
    let length = l.len(); 
    // If the vector is empty, we return None
    if length == 0 {
        return None;
    }

    // Create a clone of our list and sort it by applying our comparator function
    let mut sorted_vec = l.clone();
    sorted_vec.sort_by(cmp_func);

    // If the vector's length is even, we find the two middle numbers, add them and divide by 2
    // Else, return the middle number
