import math

def simple_sieve(limit):
    prime = [True] * (limit + 1)
    p = 2
    while p * p <= limit:
        if prime[p]:
            for i in range(p * p, limit + 1, p):
                prime[i] = False
        p += 1
    return [p for p in range(2, limit + 1) if prime[p]]

def compute_segment(low, high, primes):
    is_prime = [True] * (high - low + 1)
    for p in primes:
        start = max(p * p, low + (p - low % p) % p)
        for i in range(start, high + 1, p):
            is_prime[i - low] = False
    for i in range(0, high - low + 1):
        if is_prime[i] and (low + i >= 2):
            yield low + i

def segmented_sieve(start, end):
    if end < 2 or start > end:
        return []
    primes = simple_sieve(int(math.isqrt(end)) + 1)
    return list(compute_segment(start, end, primes))

