class TreeNode:
    def __init__(self, value=0):
        self.value = value
        self.left = None
        self.right = None

def sum_of_binary_tree(node):
    if node is None:
        return 0
    return node.value + sum_of_binary_tree(node.left) + sum_of_binary_tree(node.right)

def main():
    n = int(input())
    nodes = []
    children = []
    for _ in range(n):
        value, left_idx, right_idx = map(int, input().split())
        nodes.append(TreeNode(value))
        children.append((left_idx, right_idx))
    for idx, (left_idx, right_idx) in enumerate(children):
        if left_idx != -1:
            nodes[idx].left = nodes[left_idx]
        if right_idx != -1:
            nodes[idx].right = nodes[right_idx]
    total = sum_of_binary_tree(nodes[0] if n > 0 else None)
    print(total)

