class HashTable:
    def __init__(self, size=10):
        self.size = size
        self.table = [[] for _ in range(self.size)]

    def _hash_function(self, key):
        return key % self.size

    def insert(self, key, value):
        index = self._hash_function(key)
        for pair in self.table[index]:
            if pair[0] == key:
                pair[1] = value  # Update existing key
                return
        self.table[index].append([key, value])  # Insert new key-value pair

    def get(self, key):
        index = self._hash_function(key)
        for pair in self.table[index]:
            if pair[0] == key:
                return pair[1]
        return None  # Key not found

def main():
    n = int(input())
    if n < 0:
        print("Index cannot be negative")
        return
    elif n == 0:
        print(0)
        return
    elif n == 1:
        print(1)
        return

    fib_table = HashTable(size=n+1)
    fib_table.insert(0, 0)
    fib_table.insert(1, 1)

    for i in range(2, n + 1):
        fib_n_minus_1 = fib_table.get(i-1)
        fib_n_minus_2 = fib_table.get(i-2)
        fib_table.insert(i, fib_n_minus_1 + fib_n_minus_2)

    print(fib_table.get(n))

if __name__ == "__main__":
