```java
import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] array = {5, 6, 4, 2, 10, 3, 8, 12};
        int num = 7;  // let's use 7 as the given number to compare
        array = removeValues(array, num);
        System.out.println(Arrays.toString(array));
    }

    static int[] removeValues(int[] array, int num) {
        ArrayList<Integer> arrayList = new ArrayList<>();
        for(int val : array) {
            if(val <= num)
                arrayList.add(val);
        }
        int[] result = new int[arrayList.size()];
        for(int i = 0; i < arrayList.size(); i++) {
            result[i] = arrayList.get(i);
        }
        return result;
    }
}
