def find_positions(nums, target):
    def findLeft(nums, target):
        index = -1
        low, high = 0, len(nums) - 1
        while low <= high:
            mid = (low + high) // 2
            if nums[mid] == target:
                index = mid
                high = mid - 1
            elif nums[mid] > target:
                high = mid - 1
            else:
                low = mid + 1
        return index
    def findRight(nums, target):
        index = -1
        low, high = 0, len(nums) - 1
        while low <= high:
            mid = (low + high) // 2
            if nums[mid] == target:
                index = mid
                low = mid + 1
            elif nums[mid] > target:
                high = mid - 1
            else:
                low = mid + 1
        return index
    left, right = findLeft(nums, target), findRight(nums, target)
    return left, right

def main():
    nums = list(map(int, input().strip().split()))
    target = int(input().strip())
