The prime factorization of 5! is $2^3 \times 3^1 \times 5^1$. The highest power of an odd prime factor that can divide 5! without a remainder is thus 1, corresponding to the prime factors 3 and 5. 

However, if you'd like to use Python to solve this problem, you could write a program that calculates the prime factorization of 5! and finds the highest power of an odd prime factor. Doing this in Python would look something like this:

```python
import sympy

def prime_factors(n):
    return sympy.factorint(n)

def highest_power_odd_prime_factor(n):
    factors = prime_factors(n)
    odd_factors = {k: v for k, v in factors.items() if k%2 != 0}
    return max(odd_factors.values())

highest_power_odd_prime_factor(sympy.factorial(5))
```

When run, this program would output '1'. The first function calculates the prime factorization of a number 'n'. The second function filters the results to only include odd factors, and then finds the highest power. The final line calculates 5!, and then finds the highest power of an odd prime factor that can divide it without a remainder.

import json
import sys

def filter_dict(d, keys):
    if not isinstance(d, dict):
        return d
    return {
        k: filter_dict(v, keys)
        for k, v in d.items()
        if k in keys and not isinstance(v, dict)
           or (k in keys and isinstance(v, dict))
           or (isinstance(v, dict) and any(subk in keys for subk in v.keys()))
    }

def recursive_filter(d, keys):
    if isinstance(d, dict):
        filtered = {}
        for k, v in d.items():
            if k in keys:
                if isinstance(v, dict):
                    filtered[k] = recursive_filter(v, keys)
                else:
                    filtered[k] = v
            elif isinstance(v, dict):
                nested = recursive_filter(v, keys)
                if nested:
                    filtered[k] = nested
        return filtered
    elif isinstance(d, list):
        return [recursive_filter(item, keys) for item in d]
    else:
        return d

def main():
    data = sys.stdin.readline().strip()
    keys = sys.stdin.readline().strip()
    dataset = json.loads(data)
    keylist = json.loads(keys)
    filtered_data = recursive_filter(dataset, set(keylist))
    print(json.dumps(filtered_data))

