        if self._authenticate(pin):
            if amount > self.balance:
                print("Insufficient funds.")
            elif amount <= 0:
                print("Withdrawal amount must be positive.")
            else:
                self.balance -= amount
                print(f"Successfully withdrew ${amount}. New balance: ${self.balance}")
        else:
            print("Access denied: Incorrect PIN.")

    def change_pin(self, old_pin, new_pin):
        if self._authenticate(old_pin):
            self.pin = new_pin
            print("PIN changed successfully.")
        else:
            print("Access denied: Incorrect old PIN.")

    def _authenticate(self, pin):
