                stack.push(int(token))
            elif token in '+-*/':
                if stack.size() < 2:
                    print('Invalid postfix expression')
                    return
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.push(a + b)
                elif token == '-':
