                elif token == '*':
                    stack.push(a * b)
                elif token == '/':
                    if b == 0:
                        print('Division by zero')
                        return
                    stack.push(a // b)
            else:
                print(f'Invalid token: {token}')
                return
        if stack.size() != 1:
