def liang_barsky(x_min, y_min, x_max, y_max, x0, y0, x1, y1):
    t0 = 0.0
    t1 = 1.0
    dx = x1 - x0
    dy = y1 - y0
    p = [-dx, dx, -dy, dy]
    q = [x0 - x_min, x_max - x0, y0 - y_min, y_max - y0]
    for i in range(4):
        if p[i] == 0:
            if q[i] < 0:
                return False  # line is parallel and outside
            continue
        t = q[i] / p[i]
        if p[i] < 0:
            if t > t1:
                return False
            if t > t0:
                t0 = t
        else:
            if t < t0:
                return False
            if t < t1:
                t1 = t
    return t0 <= t1 and t0 <= 1 and t1 >= 0

