            memo[(i, j)] = len(str2) - j
            return memo[(i, j)]
        if j == len(str2):
            memo[(i, j)] = len(str1) - i
            return memo[(i, j)]
        if str1[i] == str2[j]:
            cost = 0
        else:
            cost = 1
        res = min(
            helper(i + 1, j) + 1,      # deletion
            helper(i, j + 1) + 1,      # insertion
            helper(i + 1, j + 1) + cost   # substitution
        )
        memo[(i, j)] = res
        return res
    return helper(0, 0)

