function calculateFibSum(number) {
    if (number < 0) {
        return 0;
    }
    let fibSequence = [];
    if (number === 0) {
        fibSequence = [0];
    } else {
        fibSequence = [0, 1];
        while (true) {
            const nextTerm = fibSequence[fibSequence.length - 1] + fibSequence[fibSequence.length - 2];
            if (nextTerm > number) {
                break;
            }
            fibSequence.push(nextTerm);
        }
    }
    const sum = fibSequence.reduce((acc, val) => acc + val, 0);
    return sum;
}

