def calculate_median_duration(durations):
    if not durations:
        return None

    durations.sort()
    n = len(durations)
    mid = n // 2

    if n % 2 == 0:
        median = (durations[mid - 1] + durations[mid]) / 2
    else:
        median = durations[mid]

    return int(median)

