class Node:
    def __init__(self, data, previous=None, next=None):
        self.data = data
        self.previous = previous
        self.next = next
        self.index = -1

class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.size = 0

    def _update_indices(self, start_index):
        current = self.get_node_at_index(start_index)
        index = start_index
        while current:
            current.index = index
            current = current.next
            index += 1

    def add(self, data):
        new_node = Node(data)
        if self.head is None:
            self.head = self.tail = new_node
        else:
            new_node.previous = self.tail
            self.tail.next = new_node
            self.tail = new_node
        new_node.index = self.size
        self.size += 1

    def remove(self, data):
        current = self.head
        while current:
            if current.data == data:
                if current.previous:
                    current.previous.next = current.next
                if current.next:
                    current.next.previous = current.previous
                if current == self.head:
                    self.head = current.next
                if current == self.tail:
                    self.tail = current.previous
                idx = current.index
                self.size -= 1
                self._update_indices(idx)
                return True
            current = current.next
        return False

    def find(self, data):
        current = self.head
        while current:
            if current.data == data:
                return current.index
            current = current.next
        return -1

    def get_node_at_index(self, index):
        if not 0 <= index < self.size:
            return None
        current = self.head
        for _ in range(index):
            current = current.next
        return current

    def __repr__(self):
        nodes = []
        current = self.head
        while current:
            nodes.append(f"Node({current.data}, Index={current.index})")
            current = current.next
        return " <-> ".join(nodes)

