def middle(a: int, b: int, c: int) -> int:
    # If a is the largest, the answer is the larger of b and c
    if a > b and a > c:
        return max(b, c)
    # If a is the smallest, the answer is the smaller of b and c
    if a < b and a < c:
        return min(b, c)
    # Otherwise a itself is in the middle
