def main():
    n = int(sys.stdin.readline())
    c = list(map(int, sys.stdin.readline().split()))

    # Compress consecutive duplicates
    s = []
    for colour in c:
        if not s or s[-1] != colour:
            s.append(colour)
    m = len(s)

    # Already one component
    if m <= 1:
        print(0)
        return

    # Interval DP
    dp = [[0]*m for _ in range(m)]

    for length in range(2, m+1):
        for i in range(m-length+1):
            j = i + length - 1
            if s[i] == s[j]:
                # Ends equal: we can recolour inside first, then merge
                if length == 2:
                    dp[i][j] = 0
                else:
                    dp[i][j] = dp[i+1][j-1] + 1
            else:
                # Recolour one side and proceed
                dp[i][j] = min(dp[i+1][j], dp[i][j-1]) + 1

    print(dp[0][m-1])

