from typing import List, Tuple, Any

def cache_operations(operations: List[Tuple[Any, ...]]) -> List[str]:
    """
    A very small in-memory key-value cache.

    Parameters
    ----------
    operations : List of tuples
        Each tuple encodes one cache action.

        Supported shapes are

            ('insert',  key, value)
            ('insert', (key, value))

            ('update',  key, value)
            ('update', (key, value))

            ('get',     key)
            ('delete',  key)

    Returns
    -------
    List[str]
        For every operation one string is produced:
            * 'insert' / 'update' -> 'Operation successful' (or 'Key not found'
              for an update on a non-existing key)
            * 'delete'            -> 'Operation successful' / 'Key not found'
            * 'get'               -> stored value / 'Key not found'
    """

    cache: dict = {}
    results: List[str] = []

    for op in operations:
        if not op:
            continue                       # ignore empty tuples just in case

        action = op[0]

        # Helper to normalise (key, value) extraction for insert / update
        def _extract_key_value(o: Tuple[Any, ...]):
            if len(o) == 3:                # ('insert', key, value)
                return o[1], o[2]
            elif len(o) == 2 and isinstance(o[1], tuple) and len(o[1]) == 2:
                return o[1]                # ('insert', (key, value))
            else:
                raise ValueError(f"Malformed operation tuple: {o}")

        # ---------------- Handle each action ----------------
        if action == 'insert':
            key, value = _extract_key_value(op)
            cache[key] = value
            results.append('Operation successful')

        elif action == 'update':
            key, value = _extract_key_value(op)
            if key in cache:
                cache[key] = value
                results.append('Operation successful')
            else:
                results.append('Key not found')

        elif action == 'get':
            if len(op) != 2:
                raise ValueError(f"Malformed 'get' operation: {op}")
            key = op[1]
            results.append(cache.get(key, 'Key not found'))

        elif action == 'delete':
            if len(op) != 2:
                raise ValueError(f"Malformed 'delete' operation: {op}")
            key = op[1]
            if key in cache:
                del cache[key]
                results.append('Operation successful')
            else:
                results.append('Key not found')

        else:
            raise ValueError(f"Unknown operation '{action}'")

    return results

class BankAccount:
    def __init__(self, initial_balance=0):
        if initial_balance < 0:
            raise ValueError("Initial balance cannot be negative.")
        self.balance = initial_balance

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("Deposit amount must be positive.")
        self.balance += amount
        print(f"Deposited {amount}. New balance is {self.balance}.")

    def withdraw(self, amount):
        if amount <= 0:
            raise ValueError("Withdrawal amount must be positive.")
        if amount > self.balance:
            raise ValueError("Insufficient funds for this withdrawal.")
        self.balance -= amount
        print(f"Withdrew {amount}. New balance is {self.balance}.")

    def inquire(self):
        print(f"Current balance is {self.balance}.")


