def toothpicks(n: int) -> int:
    if n == 0:
        return 0
    elif n == 1:
        return 1
    elif n == 2:
        return 3
    # n >= 3
    m = n - 2
    p = m // 2       # number of full even pairs after the first two rounds
    rem = m % 2       # 1 if n is odd, 0 if even
    return 3 + 2 * ((p + 1) * (p + 2) - 2) + rem * (4 + 2 * p)

