def find_min_max(num_list):
    """
    Return a tuple (min_value, max_value) for a list of integers.

    Parameters
    ----------
    num_list : list
        List expected to contain only integers.

    Returns
    -------
    tuple
        (minimum, maximum) if input is a non-empty list of integers;
        otherwise (None, None).

    Notes
    -----
    • Booleans are excluded even though they are subclasses of int.
    • Runs in O(n) time and O(1) extra space.
    """
    # 1) Quick checks for correct input type and non-emptiness
    if not isinstance(num_list, list) or len(num_list) == 0:
        return (None, None)

    # 2) Validate all elements and initialize min_val, max_val
    first_item = num_list[0]
    if not isinstance(first_item, int) or isinstance(first_item, bool):
        return (None, None)

    min_val = max_val = first_item

    # 3) Traverse the rest of the list
    for item in num_list[1:]:
        if not isinstance(item, int) or isinstance(item, bool):
            return (None, None)

        if item < min_val:
            min_val = item
        elif item > max_val:
            max_val = item

    return (min_val, max_val)

