import java.time.LocalDate;
import java.time.DayOfWeek;
import java.time.ZoneId;
import java.util.stream.Stream;
import java.util.Locale;
import java.util.Map;
import java.util.HashMap;
import java.util.Arrays;

public class DayOfWeekCalculator {
    public static void main(String[] args) {
        DayOfWeek day = getDayOfWeek(15, 6, 2021);
        System.out.println("Day of Week: " + day);

        Map<DayOfWeek, Long> dayOfWeekCount = getDayOfWeekCountList(1, 1, 2021, 31, 12, 2021);
        System.out.println("Day of Week Count: " + dayOfWeekCount);
    }

    public static DayOfWeek getDayOfWeek(int dayOfMonth, int month, int year) {
        LocalDate date = LocalDate.of(year, month, dayOfMonth);
        return date.getDayOfWeek();
    }

    public static Map<DayOfWeek, Long> getDayOfWeekCountList(int startDay, int startMonth, int startYear, int endDay, int endMonth, int endYear) {
        LocalDate startDate = LocalDate.of(startYear, startMonth, startDay);
        LocalDate endDate = LocalDate.of(endYear, endMonth, endDay);

        Map<DayOfWeek, Long> dayOfWeekCount = new HashMap<>();

        Stream.iterate(startDate, date -> date.plusDays(1))
              .limit(endDate.toEpochDay() - startDate.toEpochDay())
              .forEach(date -> dayOfWeekCount.merge(date.getDayOfWeek(), 1L, Long::sum));

        return dayOfWeekCount;
    }
}
