std::vector<std::string> select_merge_words(std::string s, int n) {
    std::vector<std::string> result;

    if (s == "") {
        return result;
    }

    // Declare vowels
    std::string vowels = "aeiouAEIOU";
    std::string merged_words = "";

    std::istringstream ss(s);
    std::string word;
    while (ss >> word) {
        int consonant_count = 0;
        for (char c : word) {
            if (vowels.find(c) == std::string::npos) {
                consonant_count++;
            }
        }

        if (consonant_count == n) {
            merged_words += word;
        } else {
            if (merged_words != "") {
                int vowel_count = 0;
                for (char c : merged_words) {
                    if (vowels.find(c) != std::string::npos) {
                        vowel_count++;
                    }
                }
                result.push_back(std::to_string(vowel_count) + merged_words);
                merged_words = "";
            }
        }
    }

    // Check last word.
    if (merged_words != "") {
        int vowel_count = 0;
        for (char c : merged_words) {
            if (vowels.find(c) != std::string::npos) {
                vowel_count++;
            }
        }
        result.push_back(std::to_string(vowel_count) + merged_words);
    }

    return result;
}

