    text = re.sub(r'http\S+|www\S+|https\S+', '', text, flags=re.MULTILINE)
    text = re.sub(r'@\w+', '', text)
    return text

def get_sentiment_score(text):
    positive_keywords = {'good', 'happy', 'great', 'fantastic', 'love', 'excellent', 'positive', 'wonderful', 'joy'}
    negative_keywords = {'bad', 'sad', 'terrible', 'hate', 'awful', 'negative', 'pain', 'worst', 'angry'}
    neutral_keywords = {'okay', 'fine', 'normal', 'plain', 'average', 'neutral', 'ok'}
    score = 0
    words = text.lower().split()
    for word in words:
        if word in positive_keywords:
            score += 1
        elif word in negative_keywords:
            score -= 1
        elif word in neutral_keywords:
            score += 0
    return score

def main():
    text = input()
    clean_text = remove_urls_and_mentions(text)
    score = get_sentiment_score(clean_text)
    if score > 0:
        print('positive')
    elif score < 0:
        print('negative')
    else:
        print('neutral')

