class TreeNode:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

def serialize(root):
    if not root:
        return "#"
    return str(root.val) + " " + serialize(root.left) + " " + serialize(root.right)

def deserialize(data):
    def helper(values):
        value = next(values)
        if value == "#":
            return None
        node = TreeNode(int(value))
        node.left = helper(values)
        node.right = helper(values)
        return node
    values = iter(data.strip().split())
    return helper(values)

