def fixedPoint(arr):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left+right) // 2
        if arr[mid] < mid:
            left = mid + 1
        elif arr[mid] > mid:
            right = mid - 1
        else:
            if mid == 0 or arr[mid-1] < mid - 1:
                return mid
            right = mid - 1
    return -1
