def serialize(root):
    def helper(node):
        if not node:
            return 'None,'
        return str(node.val) + ',' + helper(node.left) + helper(node.right)
    return helper(root)

def deserialize(data_iter):
    val = next(data_iter)
    if val == 'None':
        return None
    node = TreeNode(int(val))
    node.left = deserialize(data_iter)
    node.right = deserialize(data_iter)
    return node

def main():
