def sum_of_squares_in_range(start: int, end: int) -> int:
    """
    Return the sum of the squares of all integers in the inclusive range
    [start, end].  If start > end, return 0.
    """
    if start > end:
        return 0

    # Helper: sum of squares from 1 to n for non-negative n
    def S(n: int) -> int:
        # For n == 0, the value is 0; the formula also yields 0.
        return n * (n + 1) * (2 * n + 1) // 6

    # Case 1: entire interval non-negative
    if start >= 0:
        return S(end) - S(start - 1)

    # Case 2: entire interval non-positive
    if end <= 0:
        # Squares are the same as for the corresponding positive values.
        # Example: sum_{i=-5}^{-2} i^2 = sum_{j=2}^{5} j^2
        return S(abs(start)) - S(abs(end) - 1)

    # Case 3: interval crosses zero (start < 0 < end)
    # Negative part  : start .. -1
    # Positive part  : 1 .. end
    # Zero contributes 0^2 = 0, so can be ignored.
    return S(abs(start)) + S(end)

