        for _ in range(K):
            x1 = int(next(it)); y1 = int(next(it)); x2 = int(next(it)); y2 = int(next(it))
            kiosks.append((x1, y1, x2, y2))
        pipes = []
        for _ in range(P):
            x1 = int(next(it)); y1 = int(next(it)); x2 = int(next(it)); y2 = int(next(it))
            pipes.append((x1, y1, x2, y2))

        sum1 = 0  # kiosks with at least one endpoint strictly inside
        sum2 = 0  # kiosks intersected but with no endpoints inside

        for kx1, ky1, kx2, ky2 in kiosks:
            has_endpoint = False
            for x0, y0, x1p, y1p in pipes:
                # check first endpoint
                if kx1 < x0 < kx2 and ky1 < y0 < ky2:
                    has_endpoint = True
                    break
                # check second endpoint
                if kx1 < x1p < kx2 and ky1 < y1p < ky2:
                    has_endpoint = True
                    break
            area = (kx2 - kx1) * (ky2 - ky1)
            if has_endpoint:
                sum1 += area
            else:
