class BankAccount:
    def __init__(self, initial_balance=0):
        if initial_balance < 0:
            raise ValueError("Initial balance cannot be negative.")
        self.balance = initial_balance

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("Deposit amount must be positive.")
        self.balance += amount
        print(f"Deposited {amount}. New balance is {self.balance}.")

    def withdraw(self, amount):
        if amount <= 0:
            raise ValueError("Withdrawal amount must be positive.")
        if amount > self.balance:
            raise ValueError("Insufficient funds for this withdrawal.")
        self.balance -= amount
        print(f"Withdrew {amount}. New balance is {self.balance}.")

    def inquire(self):
        print(f"Current balance is {self.balance}.")


def main():
    try:
        initial_line = input().strip()
        initial_balance = int(initial_line)
        account = BankAccount(initial_balance)
    except ValueError as e:
        print(f"Transaction failed: {e}")
        return

    while True:
        try:
            line = input().strip()
        except EOFError:
            break
        if not line:
            continue
        if line == 'exit':
            break
        parts = line.split()
        if parts[0] == 'deposit' and len(parts) == 2:
            try:
                amount = int(parts[1])
                account.deposit(amount)
            except ValueError as e:
                print(f"Transaction failed: {e}")
        elif parts[0] == 'withdraw' and len(parts) == 2:
            try:
                amount = int(parts[1])
                account.withdraw(amount)
            except ValueError as e:
                print(f"Transaction failed: {e}")
        elif parts[0] == 'balance' and len(parts) == 1:
            account.inquire()
        else:
            print("Transaction failed: Invalid command.")

if __name__ == "__main__":
    main()

