While calculating the perimeter of an ellipse using just the semi-major and semi-minor axes isn't entirely precise (the exact form involves an integral that cannot be solved in terms of elementary functions) a good approximation can be obtained using Ramanujan's approximation:

Perimeter ≈ π [ 3(a+b) - √( (3a + b) * (a + 3b) ) ]

Here is the JavaScript function to implement this:

```JavaScript
function calculatePerimeter(semi_major, semi_minor) {

   let a = semi_major;
   let b = semi_minor;

   let perimeter = Math.PI * ( 3*(a + b) - Math.sqrt((3*a + b) * (a + 3*b)) );

   return perimeter;
}

let semi_major = 5; 
let semi_minor = 3; 

console.log(calculatePerimeter(semi_major, semi_minor));
```

This program creates a function called calculatePerimeter that takes two arguments: the semi-major axis and the semi-minor axis of an elliptical figure. It uses Ramanujan's approximation to calculate and return the perimeter of the ellipse. The parameters are then defined and the function is called with these parameters, logging the result to the console.

class Stack:
    def __init__(self):
        self.stack = []

    def push(self, item):
        if self.is_empty():
            self.stack.append((item, item))
        else:
            current_min = self.stack[-1][1]
            try:
                new_min = min(current_min, item)
            except TypeError:
                # If types cannot be compared, fallback to current_min
                new_min = current_min
            self.stack.append((item, new_min))

    def pop(self):
        if self.is_empty():
            print('IndexError: pop from empty stack')
        else:
            item, _ = self.stack.pop()
            print(item)

    def peek(self):
        if self.is_empty():
            print('IndexError: peek from empty stack')
        else:
            item, _ = self.stack[-1]
            print(item)

    def is_empty(self):
        return len(self.stack) == 0

    def min(self):
        if self.is_empty():
            print('IndexError: min from empty stack')
        else:
            _, current_min = self.stack[-1]
            print(current_min)

def parse_item(x):
    try:
        return int(x)
    except ValueError:
        return x

def main():
    stack = Stack()
    while True:
        try:
            line = input()
        except EOFError:
            break
        line = line.strip()
        if not line:
            continue
        if line == 'quit':
            break
        if line.startswith('push '):
            val = line[5:]
            stack.push(parse_item(val))
        elif line == 'pop':
            stack.pop()
        elif line == 'peek':
            stack.peek()
        elif line == 'is_empty':
            print(stack.is_empty())
        elif line == 'min':
            stack.min()

