    if res is not None:
        out = []
        for d in res:
            if d == float('inf'):
                out.append('inf')
            else:
                # Avoid printing unnecessary decimals (e.g. just -1 instead of -1.0 if exact)
                if d == int(d):
                    out.append(str(int(d)))
                else:
                    out.append(str(d))
        print(' '.join(out))

