def bellman_ford(graph, src):
    V = len(graph)
    dist = [float('inf')] * V
    dist[src] = 0.0
    for _ in range(V - 1):
        for u in range(V):
            for v in range(V):
                if graph[u][v] != 0.0 and dist[u] != float('inf'):
                    if dist[u] + graph[u][v] < dist[v]:
                        dist[v] = dist[u] + graph[u][v]
    for u in range(V):
        for v in range(V):
            if graph[u][v] != 0.0 and dist[u] != float('inf'):
                if dist[u] + graph[u][v] < dist[v]:
                    print("Graph contains a negative weight cycle")
                    return None
    return dist

