def sum_of_squares_in_range(start: int, end: int) -> int:
    """
    Return the sum of the squares of all integers in the inclusive range
    [start, end].  If start > end, return 0.
    """
    if start > end:
        return 0

    # Helper: sum of squares from 1 to n for non-negative n
    def S(n: int) -> int:
        # For n == 0, the value is 0; the formula also yields 0.
        return n * (n + 1) * (2 * n + 1) // 6

    # Case 1: entire interval non-negative
    if start >= 0:
        return S(end) - S(start - 1)

    # Case 2: entire interval non-positive
    if end <= 0:
        # Squares are the same as for the corresponding positive values.
        # Example: sum_{i=-5}^{-2} i^2 = sum_{j=2}^{5} j^2
        return S(abs(start)) - S(abs(end) - 1)

    # Case 3: interval crosses zero (start < 0 < end)
    # Negative part  : start .. -1
    # Positive part  : 1 .. end
    # Zero contributes 0^2 = 0, so can be ignored.
    return S(abs(start)) + S(end)

To solve this problem, we can implement an algorithm called QuickSelect which is an in-place variant of QuickSort. It uses partitioning just like quicksort, but chooses a "pivot" randomly and only recurses into one side (the one that has the nth smallest number in our case).

Here's the Python code for it:

```python
def partition(lst, low, high):
    i = (low - 1)         # index of smaller element
    pivot = lst[high]     # pivot

    for j in range(low, high):
        # If current element is smaller than or
        # equal to pivot
        if lst[j] <= pivot:
            # increment index of smaller element
            i = i + 1
            lst[i], lst[j] = lst[j], lst[i]

    lst[i + 1], lst[high] = lst[high], lst[i + 1]
    return i + 1

def quick_select(lst, low, high, k):
    if 1 <= k <= high - low + 1:
        index = partition(lst, low, high)
        if index - low == k-1:
            return lst[index]
        if index - low > k-1:
            return quick_select(lst, low, index - 1, k)
        return quick_select(lst, index + 1, high, k - index + low - 1)
    return float('inf')

