def categorize_sound_events(input_events):
    output = {
        "dialogue": [],
        "background music": [],
        "sound effects": []
    }

    for event in input_events:
        timestamp, description = event
        if description.startswith("dialogue:"):
            output["dialogue"].append(event)
        elif description.startswith("background music:"):
            output["background music"].append(event)
        elif description.startswith("sound effect:"):
            output["sound effects"].append(event)

