class Stack:
    def __init__(self):
        self.items = [None] * 100
        self.top = -1

    def push(self, item):
        if self.top == 99:
            raise Exception("Stack Overflow")
        self.top += 1
        self.items[self.top] = item

    def pop(self):
        if self.top == -1:
            raise Exception("Stack Underflow")
        item = self.items[self.top]
        self.items[self.top] = None
        self.top -= 1
        return item

    def is_empty(self):
        return self.top == -1

    def size(self):
        return self.top + 1

import sys

def main():
    import sys
    line = sys.stdin.readline().strip()
    stack = Stack()
    tokens = line.split()
    try:
        for token in tokens:
            if token.isdigit() or (token.startswith('-') and len(token) > 1 and token[1:].isdigit()):
                stack.push(int(token))
            elif token in '+-*/':
                if stack.size() < 2:
                    print('Invalid postfix expression')
                    return
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.push(a + b)
                elif token == '-':
                    stack.push(a - b)
                elif token == '*':
                    stack.push(a * b)
                elif token == '/':
                    if b == 0:
                        print('Division by zero')
                        return
                    stack.push(a // b)
            else:
                print(f'Invalid token: {token}')
                return
        if stack.size() != 1:
            print('Invalid postfix expression')
        else:
            print(stack.pop())
    except Exception as e:
        print('Invalid postfix expression')

