            if (merged_words != "") {
                int vowel_count = 0;
                for (char c : merged_words) {
                    if (vowels.find(c) != std::string::npos) {
                        vowel_count++;
                    }
                }
                result.push_back(std::to_string(vowel_count) + merged_words);
                merged_words = "";
