from typing import List, Tuple, Dict

def build_thesaurus(word_data: List[Tuple[str, List[str], List[str]]]) -> Dict[str, Dict[str, List[str]]]:
    """
    Builds a thesaurus-style dictionary from a list of (word, synonyms, antonyms) tuples.

    Parameters
    ----------
    word_data : List[Tuple[str, List[str], List[str]]]
        Each tuple contains:
            - word (str)
            - list of synonyms (List[str])
            - list of antonyms (List[str])

    Returns
    -------
    Dict[str, Dict[str, List[str]]]
        {
            word1: {
                "synonyms": [...],
                "antonyms": [...]
            },
            word2: {
                "synonyms": [...],
                "antonyms": [...]
            },
            ...
        }
    """
    thesaurus: Dict[str, Dict[str, List[str]]] = {}

    for word, synonyms, antonyms in word_data:
        # Initialize entry if this is the first time we see the word
        if word not in thesaurus:
            thesaurus[word] = {"synonyms": [], "antonyms": []}

        # Add synonyms, avoiding duplicates
        for syn in synonyms:
            if syn not in thesaurus[word]["synonyms"]:
                thesaurus[word]["synonyms"].append(syn)

        # Add antonyms, avoiding duplicates
        for ant in antonyms:
            if ant not in thesaurus[word]["antonyms"]:
                thesaurus[word]["antonyms"].append(ant)

    return thesaurus

