from collections import deque

class TreeNode:
    def __init__(self, val=0):
        self.val = val
        self.left = None
        self.right = None

def main():
    n = int(input())
    if n == 0:
        return
    nodes = [None for _ in range(n)]
    children = [[] for _ in range(n)]
    for i in range(n):
        line = input().strip()
        value, left_idx, right_idx = line.split()
        value = int(value)
        left_idx = int(left_idx)
        right_idx = int(right_idx)
        nodes[i] = TreeNode(value)
        children[i] = (left_idx, right_idx)
    for i in range(n):
        l, r = children[i]
        if l != -1:
            nodes[i].left = nodes[l]
        if r != -1:
            nodes[i].right = nodes[r]
    root = nodes[0]
    queue = deque([root])
    left_to_right = True
    while queue:
        level_size = len(queue)
        level_nodes = []
        for _ in range(level_size):
            node = queue.popleft()
            if left_to_right:
                level_nodes.append(node.val)
            else:
                level_nodes.insert(0, node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        print(' '.join(map(str, level_nodes)))
        left_to_right = not left_to_right

