def most_frequent(array):
   count = {}
   max_count = 0
   max_item = None

   for val in array:
      if val not in count:
         count[val] = 1
      else:
         count[val] += 1

      if count[val] > max_count:
         max_count = count[val]
         max_item = val

   return max_item

