def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def calculate_cubic_values(min, max):
    prime_exists = False
    for num in range(min, max + 1):
        if is_prime(num):
            prime_exists = True
            print(f"The cubic value of prime number {num} is {num**3}")
    if not prime_exists:
        print("No prime number exists in the given range.")

calculate_cubic_values(1, 100)
