def liang_barsky(x_min, y_min, x_max, y_max, x0, y0, x1, y1):
    t0 = 0.0
    t1 = 1.0
    dx = x1 - x0
    dy = y1 - y0
    p = [-dx, dx, -dy, dy]
    q = [x0 - x_min, x_max - x0, y0 - y_min, y_max - y0]
    for i in range(4):
        if p[i] == 0:
            if q[i] < 0:
                return False  # line is parallel and outside
            continue
        t = q[i] / p[i]
        if p[i] < 0:
            if t > t1:
                return False
            if t > t0:
                t0 = t
        else:
            if t < t0:
                return False
            if t < t1:
                t1 = t
    return t0 <= t1 and t0 <= 1 and t1 >= 0

def main():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    T = int(next(it))
    for _ in range(T):
        K = int(next(it)); P = int(next(it))
        kiosks = []
        for _ in range(K):
            x1 = int(next(it)); y1 = int(next(it)); x2 = int(next(it)); y2 = int(next(it))
            kiosks.append((x1, y1, x2, y2))
        pipes = []
        for _ in range(P):
            x1 = int(next(it)); y1 = int(next(it)); x2 = int(next(it)); y2 = int(next(it))
            pipes.append((x1, y1, x2, y2))

        sum1 = 0  # kiosks with at least one endpoint strictly inside
        sum2 = 0  # kiosks intersected but with no endpoints inside

        for kx1, ky1, kx2, ky2 in kiosks:
            has_endpoint = False
            for x0, y0, x1p, y1p in pipes:
                # check first endpoint
                if kx1 < x0 < kx2 and ky1 < y0 < ky2:
                    has_endpoint = True
                    break
                # check second endpoint
                if kx1 < x1p < kx2 and ky1 < y1p < ky2:
                    has_endpoint = True
                    break
            area = (kx2 - kx1) * (ky2 - ky1)
            if has_endpoint:
                sum1 += area
            else:
                intersects = False
                for x0, y0, x1p, y1p in pipes:
                    if liang_barsky(kx1, ky1, kx2, ky2, x0, y0, x1p, y1p):
                        intersects = True
                        break
                if intersects:
                    sum2 += area
        print(sum1, sum2)

