```python
from math import isqrt
from itertools import compress, count

def isprime(n):
    if n in (2, 3):
        return True
    if n % 2 == 0 or n < 2:
        return False
    for i in range(3, isqrt(n) + 1, 2):
        if n % i == 0:
            return False
    return True

def primesbelow(N):
    assert N>=2
    sieve = bytearray([(i%2 != 0) for i in range(N)])
    for x in range(3,int(N**0.5)+1,2):
        for y in range(3,(N-x)//2+1,2):
            sieve[(x*y)//2] = False
    return compress(count(), sieve)

def modify_abs_values_v3(lst, n):
    if n < 2 or n > 100:
        return -1

    primes = list(primesbelow(n + 1))

    result = 1

    for num in lst:
        value = int(abs(num))

        if value != 0 and all(value % p for p in primes):
            result *= value

    return result
```

