        return date_time.strftime('%A, %B %d at %I:%M %p, %Z')

def convert_timezone(current_tz, new_tz):
    if current_tz not in all_timezones or new_tz not in all_timezones:
        return 'Invalid timezone. Please enter a valid timezone.'
    else:
        current_date_time = datetime.now(timezone(current_tz))
        new_date_time = current_date_time.astimezone(timezone(new_tz))
