def build_tree_from_level_order(vals):
    if not vals or vals[0] == 'null':
        return None
    nodes = []
    for v in vals:
        if v == 'null':
            nodes.append(None)
        else:
            nodes.append(TreeNode(int(v)))
    kids = nodes[::-1]
