class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_tree_from_level(level_vals):
    if not level_vals or level_vals[0] == 'null':
        return None
    nodes = []
    for val in level_vals:
        if val == 'null':
            nodes.append(None)
        else:
            nodes.append(TreeNode(int(val)))
    kids = nodes[::-1]
    root = kids.pop()
    for node in nodes:
        if node:
            if kids: node.left = kids.pop()
            if kids: node.right = kids.pop()
    return root

def is_valid_bst(root):
    if not root:
        return True
    stack = [(root, float('-inf'), float('inf'))]
    while stack:
        node, lb, ub = stack.pop()
        if node.val <= lb or node.val >= ub:
            return False
        if node.left:
            # left subtree values must be strictly less than node.value
            stack.append((node.left, lb, node.val))
        if node.right:
            # right subtree values may equal node.value (for duplicates, per problem), but must be strictly greater for BST
            stack.append((node.right, node.val, ub))
    return True

