from itertools import permutations
import sys

def is_palindrome(s):
    return s == s[::-1]

def is_vowel(c):
    return c in 'aeiou'

def has_palindromic_substring_of_length_3(s):
    for i in range(len(s)-2):
        for j in range(i+3, len(s)+1):
            if is_palindrome(s[i:j]):
                return True
    return False

def contains_vowel_in_even_positions(s):
    for i in range(0, len(s), 2):
        if is_vowel(s[i]):
            return True
    return False

def has_no_consecutive_duplicates(s):
    for i in range(len(s)-1):
        if s[i] == s[i+1]:
            return False
    return True

def is_cyclic_rotation(p1, p2):
    if len(p1) != len(p2):
        return False
    return p2 in (p1 + p1)

def main():
    s = sys.stdin.readline().strip()
    original = s
    seen_reverse = set()
    seen_cyclic = set()
    valid_permutations = []

    for perm in sorted(permutations(s)):
        perm_str = ''.join(perm)
        # no character at its original position
        if any(perm_str[i] == s[i] for i in range(len(s))):
            continue
        if not has_palindromic_substring_of_length_3(perm_str):
            continue
        if not contains_vowel_in_even_positions(perm_str):
            continue
        if not has_no_consecutive_duplicates(perm_str):
            continue
        # Not anagram of reverse of any previous
        reverse_perm = perm_str[::-1]
        counts = lambda x: tuple(sorted((c, x.count(c)) for c in set(x)))
        reverse_key = counts(reverse_perm)
        if reverse_key in seen_reverse:
            continue
        seen_reverse.add(counts(perm_str))
        # No cyclic rotation of any previous
        is_cyclic = False
        for prev in seen_cyclic:
            if is_cyclic_rotation(prev, perm_str):
                is_cyclic = True
                break
        if is_cyclic:
            continue
        seen_cyclic.add(perm_str)
        valid_permutations.append(perm_str)
    for item in valid_permutations:
        print(item)

