class TemperatureConverter:
    def __init__(self):
        # All lambdas below convert x from a given scale to Celsius
        self.to_celsius = {
            'Celsius': lambda x: x,
            'Fahrenheit': lambda x: (x - 32) * 5 / 9,
            'Kelvin': lambda x: x - 273.15,
            'Reaumur': lambda x: x * 5 / 4,
            'Rankine': lambda x: (x - 491.67) * 5/9
        }
        # All lambdas below convert C to the target scale
        self.from_celsius = {
            'Celsius': lambda c: c,
            'Fahrenheit': lambda c: c * 9 / 5 + 32,
            'Kelvin': lambda c: c + 273.15,
            'Reaumur': lambda c: c * 4 / 5,
            'Rankine': lambda c: (c + 273.15) * 9/5
        }

    def convert(self, value, from_scale, to_scale):
        celsius_value = self.to_celsius[from_scale](value)
        return self.from_celsius[to_scale](celsius_value)

