def power(base, exp, memo=None):
    if memo is None:
        memo = {}
    if exp == 0:
        return 1.0
    elif exp == 1:
        return base
    elif exp == -1:
        return 1 / base
    if exp in memo:
        return memo[exp]
    # Handle negative exponents
    if exp < 0:
        return 1 / power(base, -exp, memo)
    # Handle fractional exponents
    if exp != int(exp):
        return base ** exp
    # Recursive case: divide the problem in half
    half_power = power(base, int(exp // 2), memo)
    if exp % 2 == 0:
        result = half_power * half_power
    else:
        result = half_power * half_power * base
    memo[exp] = result
    return result

def main():
    base = float(input())
    exp = float(input())
    print(power(base, exp))

