class HashTable:
    def __init__(self, size=101):
        self.size = size
        self.slots = [None] * size
        self.data = [None] * size

    def hash_function(self, key):
        return key % self.size

    def quadratic_rehash(self, old_hash, i):
        return (old_hash + i * i) % self.size

    def put(self, key, data):
        hash_value = self.hash_function(key)

        if self.slots[hash_value] is None:
            self.slots[hash_value] = key
            self.data[hash_value] = data
        else:
            if self.slots[hash_value] == key:
                self.data[hash_value] = data  # replace
            else:
                i = 1
                next_slot = self.quadratic_rehash(hash_value, i)
                while self.slots[next_slot] is not None and self.slots[next_slot] != key:
                    i += 1
                    next_slot = self.quadratic_rehash(hash_value, i)
                if self.slots[next_slot] is None:
                    self.slots[next_slot] = key
                    self.data[next_slot] = data
                else:
                    self.data[next_slot] = data  # replace

    def get(self, key):
        hash_value = self.hash_function(key)
        data = None
        stop = False
        found = False
        position = hash_value

        i = 1
        while self.slots[position] is not None and not found and not stop:
            if self.slots[position] == key:
                found = True
                data = self.data[position]
            else:
                position = self.quadratic_rehash(hash_value, i)
                i += 1
                if position == hash_value:
                    stop = True
        return data

    def __getitem__(self, key):
        return self.get(key)

    def __setitem__(self, key, data):
        self.put(key, data)

    def __contains__(self, key):
        return self.get(key) is not None

def lucas(n, memo=None):
    if memo is None:
        memo = HashTable()
    if n in memo:
        return memo[n]
    if n == 0:
        memo[n] = 2
        return 2
    elif n == 1:
        memo[n] = 1
        return 1
    else:
        result = lucas(n-1, memo) + lucas(n-2, memo)
        memo[n] = result
        return result

def main():
    n = int(input())
    print(lucas(n))

