            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if 'PRIVATE' in new_key:
                continue
            items.extend(flatten(v, new_key, sep=sep, seen=seen).items())
        return dict(items)
    elif isinstance(d, list):
        items = []
        for i, v in enumerate(d):
            new_key = f"{parent_key}[{i}]"
            items.extend(flatten(v, new_key, sep=sep, seen=seen).items())
        return dict(items)
    else:
        # Primitive type
        if isinstance(d, float):
            return {parent_key: round_half_even(d)}
        elif isinstance(d, str):
            # Replace all '7' (digit char) with 'L', regardless of presence in the string
            return {parent_key: d.replace('7', 'L').upper()}
        else:
            return {parent_key: d}

