class Stack:
    def __init__(self):
        self.items = [None] * 100
        self.top = -1

    def push(self, item):
        if self.top == 99:
            raise Exception("Stack Overflow")
        self.top += 1
        self.items[self.top] = item

    def pop(self):
        if self.top == -1:
            raise Exception("Stack Underflow")
        item = self.items[self.top]
        self.items[self.top] = None
        self.top -= 1
        return item

    def is_empty(self):
        return self.top == -1

    def size(self):
        return self.top + 1

import sys

def main():
