    line = sys.stdin.readline().strip()
    stack = Stack()
    tokens = line.split()
    try:
        for token in tokens:
            if token.isdigit() or (token.startswith('-') and len(token) > 1 and token[1:].isdigit()):
                stack.push(int(token))
            elif token in '+-*/':
                if stack.size() < 2:
                    print('Invalid postfix expression')
                    return
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.push(a + b)
                elif token == '-':
                    stack.push(a - b)
                elif token == '*':
                    stack.push(a * b)
                elif token == '/':
                    if b == 0:
                        print('Division by zero')
                        return
                    stack.push(a // b)
            else:
                print(f'Invalid token: {token}')
                return
        if stack.size() != 1:
            print('Invalid postfix expression')
        else:
            print(stack.pop())
    except Exception as e:
