        return n_str.isdigit()

    def factorial(self, n):
        if not self.is_non_negative_integer(n):
            raise ValueError("Input must be a non-negative integer")
        n_int = int(n)
        if n_int == 0:
            return 1
        else:
            return n_int * self.factorial(n_int - 1)

