The requirements of this prompt are too complex, and the problem is not well defined, especially for negative, non-integer, and complex numbers. Moreover, the definition of a factor is only applicable to positive integers. Lastly, Python's standard library doesn't provide comprehensive support for mathematical operations on complex numbers, such as finding all complex roots of a number.

However, I will design the function in a way that handles computation of factor for positive integers.

```python
def is_prime(n):
    if n is None:
        return False
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def calculate_factors(num):
    factors = [i for i in range(1, num + 1) if num % i == 0]
    return factors

def calculate_lcm(num1, num2):
    if num1 > num2:
        greater = num1
    else:
        greater = num2
    while True:
        if greater % num1 == 0 and greater % num2 == 0:
            lcm = greater
            break
        greater += 1
    return lcm

def check_number(input_number):

    try:
        number = int(input_number)
    except ValueError:
        return {input_number: ('The input should be a non-negative integer', [], None, None, None)}

    if number < 0:
        return {input_number: ('The input should be a non-negative integer', [], None, None, None)}
    if number <= 1:
        return {input_number: (False, [number], number, number, None)}

    factors = calculate_factors(number)
    factors_sum = sum(factors)
    prime_factors = [factor for factor in factors if is_prime(factor)]
    max_prime = max(prime_factors) if prime_factors else None

    lcm, gcd = None, None
    if len(factors) > 1:
        gcd = min(factors)
        lcm = calculate_lcm(factors[0], factors[1])
        for factor in factors[2:]:
            lcm = calculate_lcm(lcm, factor)

    output_tuple = (len(factors) % 2 == 0, factors, factors_sum, max_prime, (lcm, gcd))
    return {input_number: output_tuple}

def process_multiple_inputs(*inputs):
    result = {}
    for input_number in inputs:
        result.update(check_number(input_number))

    return result

```

