class ATM:
    def __init__(self):
        self.balance = 0.0
        self.pin = '1234'

    def check_balance(self, pin):
        if self._authenticate(pin):
            print(f"Your balance is: ${self.balance}")
        else:
            print("Access denied: Incorrect PIN.")

    def deposit(self, pin, amount):
        if self._authenticate(pin):
            if amount > 0:
                self.balance += amount
                print(f"Successfully deposited ${amount}. New balance: ${self.balance}")
            else:
                print("Deposit amount must be positive.")
        else:
            print("Access denied: Incorrect PIN.")

    def withdraw(self, pin, amount):
        if self._authenticate(pin):
            if amount > self.balance:
                print("Insufficient funds.")
            elif amount <= 0:
                print("Withdrawal amount must be positive.")
            else:
                self.balance -= amount
                print(f"Successfully withdrew ${amount}. New balance: ${self.balance}")
        else:
            print("Access denied: Incorrect PIN.")

    def change_pin(self, old_pin, new_pin):
        if self._authenticate(old_pin):
            self.pin = new_pin
            print("PIN changed successfully.")
        else:
            print("Access denied: Incorrect old PIN.")

    def _authenticate(self, pin):
        return pin == self.pin


