This implementation takes into account error handling by checking if the input is actually an array and that it only contains numbers. Performance is also considered by limiting the search for factors up to the square root of the number.

```javascript
// function to check if a number is prime
function isPrime(num) {
    if (num <= 1) return false; 
    if (num === 2) return true; 
    if (num % 2 === 0) return false; 
    let sqrt = Math.sqrt(num);
    for(let i = 3; i <= sqrt; i+=2) {
        if (num % i === 0) return false; 
    }
    return true;
}

// main function to count prime numbers in an array
function countPrimes(arr) {
    // error handling: check if input is an array
    if (!Array.isArray(arr)) {
        throw 'Input must be an array.';
    }

    // error handling: check if array elements are numbers
    for (let i = 0; i < arr.length; i++) {
        if (typeof arr[i] !== 'number') {
            throw 'Array can only include numbers.';
        }
    }

    // count the prime numbers
    let count = 0;
    for (let i = 0; i < arr.length; i++) {
        if (isPrime(arr[i])) {
            count++;
        }
    }
    return count;
}
