    except ValueError:
        return {input_number: ('The input should be a non-negative integer', [], None, None, None)}

    if number < 0:
        return {input_number: ('The input should be a non-negative integer', [], None, None, None)}
    if number <= 1:
        return {input_number: (False, [number], number, number, None)}

    factors = calculate_factors(number)
    factors_sum = sum(factors)
