def bubble_sort_stop_on_even(numbers):
    n = len(numbers)
    for i in range(n):
        for j in range(0, n-i-1):
            if numbers[j] % 2 == 0 or numbers[j+1] % 2 == 0:
                return numbers
            if numbers[j] > numbers[j+1]:
                numbers[j], numbers[j+1] = numbers[j+1], numbers[j]
    return numbers

