    if len(s) == 0:
        return s
    else:
        if s[-1].isspace():
            return reverse_string_ignore_whitespace(s[:-1])
        else:
            return s[-1] + reverse_string_ignore_whitespace(s[:-1])

def reverse_string_alpha_only(s):
    if len(s) == 0:
        return s
    else:
        if not s[-1].isalpha():
            return reverse_string_alpha_only(s[:-1])
        else:
            return s[-1] + reverse_string_alpha_only(s[:-1])

