from typing import List, Tuple, Optional

def trie_operations(operations: List[Tuple[str, str]]) -> List[Optional[bool]]:
    """
    Perform a sequence of 'add' and 'search' operations on a trie.

    Parameters
    ----------
    operations : List[Tuple[str, str]]
        Each tuple contains an operation type ('add' or 'search')
        and the word to which the operation applies.

    Returns
    -------
    List[Optional[bool]]
        For every 'search' operation, the list contains True or False
        depending on whether the word was found. For every 'add'
        operation, the list contains None.
    """

    class TrieNode:
        __slots__ = ("children", "is_end")

        def __init__(self) -> None:
            self.children: dict[str, "TrieNode"] = {}
            self.is_end: bool = False

    class Trie:
        def __init__(self) -> None:
            self.root = TrieNode()

        def insert(self, word: str) -> None:
            node = self.root
            for ch in word:
                if ch not in node.children:
                    node.children[ch] = TrieNode()
                node = node.children[ch]
            node.is_end = True

        def search(self, word: str) -> bool:
            node = self.root
            for ch in word:
                if ch not in node.children:
                    return False
                node = node.children[ch]
            return node.is_end

    trie = Trie()
    results: List[Optional[bool]] = []

    for op, word in operations:
        if op == "add":
            trie.insert(word)
            results.append(None)
        elif op == "search":
            results.append(trie.search(word))
        else:
            raise ValueError(f"Unsupported operation: {op}")

    return results

