class Stack:
    def __init__(self):
        self.stack = []

    def push(self, item):
        if self.is_empty():
            self.stack.append((item, item))
        else:
            current_min = self.stack[-1][1]
            try:
                new_min = min(current_min, item)
            except TypeError:
                # If types cannot be compared, fallback to current_min
                new_min = current_min
            self.stack.append((item, new_min))

    def pop(self):
        if self.is_empty():
            print('IndexError: pop from empty stack')
        else:
            item, _ = self.stack.pop()
            print(item)

    def peek(self):
        if self.is_empty():
            print('IndexError: peek from empty stack')
        else:
            item, _ = self.stack[-1]
            print(item)

    def is_empty(self):
        return len(self.stack) == 0

    def min(self):
        if self.is_empty():
            print('IndexError: min from empty stack')
        else:
            _, current_min = self.stack[-1]
            print(current_min)

def parse_item(x):
    try:
        return int(x)
    except ValueError:
        return x

def main():
    stack = Stack()
    while True:
        try:
            line = input()
