            stack.push(parse_item(val))
        elif line == 'pop':
            stack.pop()
        elif line == 'peek':
            stack.peek()
        elif line == 'is_empty':
            print(stack.is_empty())
        elif line == 'min':
            stack.min()

if __name__ == '__main__':
