def fibonacci_and_factorial(n):
    if not isinstance(n, int) or n < 1:
        return "Invalid input. Please enter a positive integer."

    def fibonacci(n):
        fib_values = [0, 1]
        while len(fib_values) < n:
            fib_values.append(fib_values[-1] + fib_values[-2])
        return fib_values[1:]

    def factorial(n):
        if n == 0 or n == 1:
            return 1
        else:
            return n * factorial(n-1)

    fib_series = fibonacci(n)

    for num in fib_series:
        print(f"Number: {num} , Factorial: {factorial(num)}")

fibonacci_and_factorial(15)
