class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def build_tree_from_level_order(vals):
    if not vals or vals[0] == 'null':
        return None
    nodes = []
    for v in vals:
        if v == 'null':
            nodes.append(None)
        else:
            nodes.append(TreeNode(int(v)))
    kids = nodes[::-1]
    root = kids.pop()
    for node in nodes:
        if node:
            if kids:
                node.left = kids.pop()
            if kids:
                node.right = kids.pop()
    return root

def are_identical_trees(tree1, tree2):
    if tree1 is None and tree2 is None:
        return True
    if tree1 is not None and tree2 is not None:
        return (
            tree1.val == tree2.val and
            are_identical_trees(tree1.left, tree2.left) and
            are_identical_trees(tree1.right, tree2.right)
        )
    return False

