    def helper(node):
        if not node:
            return float('-inf'), []
        if not node.get('left') and not node.get('right'):
            return node.get('val'), [node.get('val')]
        left_sum, left_path = helper(node.get('left'))
        right_sum, right_path = helper(node.get('right'))
        # Only accept paths of at least length 2 (i.e., one child below root)
        max_sum = float('-inf')
        max_path = []
        if node.get('left'):
            s, p = helper(node.get('left'))
            sum_two = node['val'] + p[0]
            if len(p) >= 1:
                candidate_sum = node['val'] + s
                candidate_path = [node['val']] + p
                if len(candidate_path) >= 2 and candidate_sum > max_sum:
                    max_sum = candidate_sum
                    max_path = candidate_path
        if node.get('right'):
