from itertools import permutations

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num**0.5)+1):
        if num % i == 0:
            return False
    return True

def smallest_prime_factor(n):
    if n <= 1:
        return None
    for i in range(2, n+1):
        if n % i == 0 and is_prime(i):
            return i

def is_square_free(num):
    if num < 2:
        return True
    i = 2
    while i*i <= num:
        if num % (i*i) == 0:
            return False
        i += 1
    return True

n = int(input())
if n % 2 == 0:
