    spf = smallest_prime_factor(n)
    if spf is None:
        print(0)
    else:
        count = 0
        for length in range(1, n+1, 2):
            for comb in permutations(digits, length):
                if comb[0] == '0' and length > 1:
                    continue
                num_str = ''.join(comb)
                if num_str != ''.join(sorted(num_str)):
                    continue
                if num_str != num_str[::-1]:
                    continue
                num = int(num_str)
                if not is_square_free(num):
                    continue
                if num % spf != 0:
                    continue
                digit_sum = sum(int(d) for d in num_str)
                if not is_prime(digit_sum):
                    continue
                count += 1
        print(count)

import sys

class DSU:
    def __init__(self, n):
        self.par = list(range(n))
    def find(self, x):
        if self.par[x] != x:
            self.par[x] = self.find(self.par[x])
        return self.par[x]
    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra != rb:
            self.par[rb] = ra

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    circles = []
    for _ in range(n):
        x = int(next(it)); y = int(next(it)); r = int(next(it))
        circles.append((x, y, r))

    dsu = DSU(n)
    V = 0  # number of intersection points (vertices)

    for i in range(n):
        x1, y1, r1 = circles[i]
        for j in range(i + 1, n):
            x2, y2, r2 = circles[j]
            dx = x2 - x1
            dy = y2 - y1
            d2 = dx * dx + dy * dy  # squared distance between centres
            sr = r1 + r2
            dr = abs(r1 - r2)
            # compare squared values to avoid floating point
            if d2 > sr * sr:
                inter = 0               # separate
            elif d2 == sr * sr:
                inter = 1               # externally tangent
            elif d2 < dr * dr:
                inter = 0               # one inside another, no touch
            elif d2 == dr * dr:
                inter = 1               # internally tangent
            else:
                inter = 2               # two proper intersection points
            if inter:
                dsu.union(i, j)
            V += inter

    # count connected components of the set of circles
    roots = {dsu.find(i) for i in range(n)}
    C = len(roots)

    regions = V + C + 1
    print(regions)

