class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

def insert(root, value):
    if root is None:
        return TreeNode(value)
    if value < root.value:
        root.left = insert(root.left, value)
    elif value > root.value:
        root.right = insert(root.right, value)
    return root

def find_max_and_second_largest(root):
    if not root:
        return None, None
    parent = None
    curr = root
    while curr.right:
        parent = curr
        curr = curr.right
    # curr is now the max node
    max_val = curr.value
    # Now find the second largest unique value
    if curr.left:
        # The second largest is the rightmost node in left subtree
        sec = curr.left
        while sec.right:
            sec = sec.right
        return max_val, sec.value
    elif parent:
        return max_val, parent.value
    else:
        # Only root node exists
        return max_val, max_val

