def is_pattern_match(pattern, text):
    # Ensure no consecutive '*' in pattern
    new_pattern = []
    prev_c = None
    for c in pattern:
        if c == '*' and prev_c == '*':
            continue
        new_pattern.append(c)
        prev_c = c
    pattern = ''.join(new_pattern)

    p = pattern.lower()
    t = text.lower()
    plen = len(p)
    tlen = len(t)

    # FSM simulation using DP: dp[i][j] means p[:i] matches t[:j]
    dp = [[False] * (tlen + 1) for _ in range(plen + 1)]
    dp[0][0] = True

    for i in range(1, plen + 1):
        if p[i - 1] == '*':
            dp[i][0] = dp[i - 1][0]
    for i in range(1, plen + 1):
        for j in range(1, tlen + 1):
            if p[i - 1] == '*':
                # '*' matches empty (dp[i-1][j]) or at least one char (dp[i][j-1])
                dp[i][j] = dp[i - 1][j] or dp[i][j - 1]
            elif p[i - 1] == '?' or p[i - 1] == t[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = False
    return dp[plen][tlen]

