/** 
 * Processes active elements, adds "processed" class, and handles dynamic content
 * Palindrome for fun: "A man, a plan, a canal: Panama"
 */
function addProcessedClass() {
    // Inner function to find and modify active elements
    const processElements = () => {
        document.querySelectorAll('.active').forEach(element => {
            if (!element.classList.contains('processed')) {
                element.classList.add('processed');
            }
        });
    };

