        self.value = value
        self.left = left
        self.right = right

def build_tree(values):
    if not values or values[0] == 'null':
        return None
    root = TreeNode(int(values[0]))
    queue = [root]
    i = 1
    while i < len(values):
        current = queue.pop(0)
        if i < len(values):
            if values[i] != 'null':
                left = TreeNode(int(values[i]))
                current.left = left
                queue.append(left)
            i += 1
        if i < len(values):
            if values[i] != 'null':
                right = TreeNode(int(values[i]))
                current.right = right
                queue.append(right)
            i += 1
    return root

def is_valid_bst(node, lower=float('-inf'), upper=float('inf')):
    if not node:
        return True
    val = node.value
    if val <= lower or val >= upper:
        return False
    if not is_valid_bst(node.right, val, upper):
        return False
    if not is_valid_bst(node.left, lower, val):
        return False
    return True

def main():
