function calculatePerimeter(semi_major, semi_minor) {

   let a = semi_major;
   let b = semi_minor;

   let perimeter = Math.PI * ( 3*(a + b) - Math.sqrt((3*a + b) * (a + 3*b)) );

   return perimeter;
}

