    assert(fibonacci(1) == 1)
    assert(fibonacci(10) == 55)
    try:
        fibonacci(-1)
    except ValueError:
        assert True
    else:
        assert False
    try:
        fibonacci(2.5)
    except TypeError:
        assert True
    else:
        assert False

test_fibonacci()
```

