    static List<int> GetPrimes(int n)
    {
        List<int> primes = new List<int>();
        int check = 2;
        while (primes.Count < n)
        {
            if (IsPrime(check))
            {
                primes.Add(check);
            }
            check++;
        }
        return primes;
    }

    static bool IsPrime(int n)
    {
        if (n <= 1)
        {
            return false;
        }
        if (n == 2)
        {
            return true;
        }
        if (n % 2 == 0)
        {
            return false;
        }

        for (int i = 3; i * i <= n; i += 2)
        {
            if (n % i == 0)
            {
                return false;
            }
        }
        return true;
    }
}
